SEED = 20261008
N_CANDIDATES = 6
N_EXEMPLARS_PER_CANDIDATE = 1
MIN_ITEMS_PER_TOPIC = 2
TEST_FRACTION_OF_TOPICS = 0.18
HARD_NEIGHBOR_RANK_LO = 2
HARD_NEIGHBOR_RANK_HI = 30
# Every reserved text may appear at most this many times across the whole
# split, as true exemplar or distractor combined. A distractor topic whose
# pool is fully capped is skipped for the next neighbour, which forces
# distractor and true-exemplar texts to recur at the same rate.
MAX_SHOWS_PER_TEXT = 6


def _load_groups():
    return json.loads(zlib.decompress(base64.b85decode(_BLOB)).decode())


def _find_raw_file(raw_dir, name):
    # The platform may mount the raw archive flat (works.jsonl at the root)
    # or preserve a dataset/raw/ prefix; resolve either without assuming.
    for candidate in (
        os.path.join(raw_dir, name),
        os.path.join(raw_dir, "raw", name),
        os.path.join(raw_dir, "dataset", "raw", name),
    ):
        if os.path.isfile(candidate):
            return candidate
    for dirpath, _, filenames in os.walk(raw_dir):
        if name in filenames:
            return os.path.join(dirpath, name)
    raise FileNotFoundError(f"{name} not found anywhere under {raw_dir}")


def _load_raw(raw_dir):
    rows = []
    seen_work_ids = set()
    with open(_find_raw_file(raw_dir, "works.jsonl")) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            r = json.loads(line)
            if r["work_id"] in seen_work_ids:
                continue
            seen_work_ids.add(r["work_id"])
            rows.append(r)

    # A handful of OpenAlex records carry boilerplate journal front-matter
    # (e.g. a journal's own self-description) as their "abstract" field,
    # identical across many unrelated works in that journal. Any abstract
    # text shared by more than one distinct work_id carries no real
    # per-work topical signal, so every work sharing it is dropped.
    abstract_counts = {}
    for r in rows:
        abstract_counts[r["abstract"]] = abstract_counts.get(r["abstract"], 0) + 1
    rows = [r for r in rows if abstract_counts[r["abstract"]] == 1]
    return rows


def _least_shown(pool, usage, rng, enforce_cap=True):
    # Pick the pool item shown fewest times so far (ties broken by seeded
    # RNG). Returns None if every item in the pool has hit MAX_SHOWS_PER_TEXT
    # and the cap is enforced (distractor use); true-exemplar use never
    # returns None so every query row is always buildable.
    low = min(usage[it["work_id"]] for it in pool)
    if enforce_cap and low >= MAX_SHOWS_PER_TEXT:
        return None
    pick = rng.choice([it for it in pool if usage[it["work_id"]] == low])
    usage[pick["work_id"]] += 1
    return pick


def _build_candidates(query_topic_id, exemplar_pool, hard_neighbors, usage, rng, true_used):
    n_needed = N_CANDIDATES - 1
    neighbor_list = hard_neighbors.get(query_topic_id, [])
    viable_neighbors = [tid for tid in neighbor_list if tid in exemplar_pool]
    banded = viable_neighbors[HARD_NEIGHBOR_RANK_LO:HARD_NEIGHBOR_RANK_HI]

    if len(banded) < n_needed:
        banded = viable_neighbors[HARD_NEIGHBOR_RANK_LO:]
    if len(banded) < n_needed:
        return None

    # Every exemplar (true or distractor) comes from a reserved pool, so no
    # exemplar text can ever be any row's query abstract. Distractor topics
    # are tried in seeded-random order; a topic whose pool is capped out is
    # skipped for the next one.
    # The true exemplar is a pool text no other row of this topic has had as
    # its true exemplar, so every row's true exemplar is its own. A topic's
    # pool is as large as its query set, so one is always left.
    fresh = [it for it in exemplar_pool[query_topic_id] if it["work_id"] not in true_used]
    true_pick = _least_shown(fresh, usage, rng, enforce_cap=False)
    candidates = [("true", true_pick)]
    order = banded[:]
    rng.shuffle(order)
    # least-exposed topics first, so every text's total exposure stays level
    order.sort(key=lambda t: sum(usage[it["work_id"]] for it in exemplar_pool[t]) / len(exemplar_pool[t]))
    for tid in order:
        if len(candidates) == N_CANDIDATES:
            break
        pick = _least_shown(exemplar_pool[tid], usage, rng)
        if pick is not None:
            candidates.append(("distractor", pick))
    if len(candidates) < N_CANDIDATES:
        return None
    true_used.add(true_pick["work_id"])

    rng.shuffle(candidates)
    true_slot = next(i for i, (kind, _) in enumerate(candidates) if kind == "true")
    return candidates, true_slot


def prepare(raw_dir, public_dir, private_dir):
    rng = random.Random(SEED)
    rows = _load_raw(raw_dir)

    # The topic grouping is embedded in this file, not read from the
    # raw archive, so no file in the data mount pairs an abstract with its
    # topic. Works absent from the grouping are simply skipped.
    groups = _load_groups()
    topic_map = groups["m"]
    hard_neighbors = groups["n"]

    topic_to_items = {}
    for r in rows:
        if r["work_id"] not in topic_map:
            continue
        tid = str(topic_map[r["work_id"]])
        topic_to_items.setdefault(tid, []).append(r)

    viable_topic_ids = sorted(tid for tid, items in topic_to_items.items() if len(items) >= MIN_ITEMS_PER_TOPIC)
    hard_neighbors = {str(k): [str(n) for n in v] for k, v in hard_neighbors.items()}

    shuffled_topics = viable_topic_ids[:]
    rng.shuffle(shuffled_topics)
    n_test_topics = max(1, int(len(shuffled_topics) * TEST_FRACTION_OF_TOPICS))
    test_topic_ids = set(shuffled_topics[:n_test_topics])
    train_topic_ids = set(shuffled_topics[n_test_topics:])

    # Split each topic in half: the first half is a reserved exemplar pool
    # whose works are never used as queries; the second half are the
    # queries. Every exemplar shown (true or distractor) is sampled per row
    # from a reserved pool, so no exemplar text ever equals any query
    # abstract, and true and distractor texts recur across rows at the same
    # rate — how often a text appears carries no information about which
    # slot is correct.
    exemplar_pool = {}
    query_items = {}
    for tid in viable_topic_ids:
        items = sorted(topic_to_items[tid], key=lambda r: r["work_id"])
        random.Random(f"{SEED}-{tid}").shuffle(items)
        half = len(items) // 2
        exemplar_pool[tid] = items[:half]
        query_items[tid] = items[half : 2 * half]

    usage = {it["work_id"]: 0 for pool in exemplar_pool.values() for it in pool}
    true_used = set()

    def build_rows(topic_id_set, split_name):
        out_rows = []
        for tid in sorted(topic_id_set):
            for item in query_items[tid]:
                out_rows.append((tid, item, split_name))
        return out_rows

    # Build every row of both splits in ONE seeded-random global order, so
    # the per-text exposure cap is spent evenly across train and test and
    # neither split's exemplars recur at a different rate than the other's.
    pending = build_rows(test_topic_ids, "test") + build_rows(train_topic_ids, "train")
    random.Random(f"{SEED}-interleave").shuffle(pending)

    built = {"test": [], "train": []}
    for tid, item, split_name in pending:
        b = _build_candidates(tid, exemplar_pool, hard_neighbors, usage, rng, true_used)
        if b is None:
            continue
        candidates, true_slot = b
        row = {"work_id": item["work_id"], "query_abstract": item["abstract"], "_topic": tid}
        for slot, (_, ex) in enumerate(candidates):
            row[f"candidate_{slot}_exemplar"] = ex["abstract"]
        row["slot"] = true_slot
        built[split_name].append(row)

    def finalize(rows):
        # Reshuffle on a stepped seed until no two consecutive rows share a
        # topic, so row order carries no topic signal.
        for attempt in range(1000):
            random.Random(f"{SEED}-order-{attempt}").shuffle(rows)
            if all(a["_topic"] != b["_topic"] for a, b in zip(rows, rows[1:])):
                break
        for r in rows:
            del r["_topic"]
        return rows

    test_rows = finalize(built["test"])
    train_rows = finalize(built["train"])

    os.makedirs(public_dir, exist_ok=True)
    os.makedirs(private_dir, exist_ok=True)

    train_df = pd.DataFrame(train_rows)
    test_full_df = pd.DataFrame(test_rows)
    test_df = test_full_df.drop(columns=["slot"])

    train_df.to_csv(os.path.join(public_dir, "train.csv"), index=False)
    test_df.to_csv(os.path.join(public_dir, "test.csv"), index=False)

    sample_submission = pd.DataFrame({"work_id": test_df["work_id"], "slot": 0})
    sample_submission.to_csv(os.path.join(public_dir, "sample_submission.csv"), index=False)

    answers_df = test_full_df[["work_id", "slot"]]
    answers_df.to_csv(os.path.join(private_dir, "answers.csv"), index=False)


if __name__ == "__main__":
    import sys

    raw_dir = sys.argv[1] if len(sys.argv) > 1 else "dataset/raw"
    public_dir = sys.argv[2] if len(sys.argv) > 2 else "dataset/public"
    private_dir = sys.argv[3] if len(sys.argv) > 3 else "dataset/private"
    prepare(raw_dir, public_dir, private_dir)
    print("prepare() complete")
